#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;



int editDistance(string a,string b)
{
    int n=a.size();
    int m=b.size();


    vector<vector<int>> dp(
        n+1,
        vector<int>(m+1)
    );



    // 初始化
    for(int i=0;i<=n;i++)
        dp[i][0]=i;


    for(int j=0;j<=m;j++)
        dp[0][j]=j;



    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=m;j++)
        {
            int cost;


            if(a[i-1]==b[j-1])
                cost=0;
            else
                cost=1;



            dp[i][j]=min({
                dp[i-1][j]+1,      // 删除
                dp[i][j-1]+1,      // 插入
                dp[i-1][j-1]+cost  // 修改
            });
        }
    }


    return dp[n][m];
}



int main()
{
    int N,M;


    cin >> N >> M;



    vector<string> dict(N);



    for(int i=0;i<N;i++)
        cin >> dict[i];



    while(M--)
    {
        string s;
        int k;


        cin >> s >> k;



        int ans=0;



        for(string word:dict)
        {
            if(editDistance(word,s)<=k)
                ans++;
        }



        cout << ans << endl;
    }



    return 0;
}
